    s = s.replace('Z', '+00:00')
    return datetime.fromisoformat(s)


data = json.load(open(sys.argv[1]))
as_of = parse_dt(data["as_of"])

result = []
for r in data.get("reminders", []):
    if r.get("completed"):
        continue
    due = r.get("due")
    if due is None or not isinstance(due, str):
        continue
    try:
        dt_due = parse_dt(due)
    except Exception:
        continue
    if dt_due.tzinfo is None:
        continue
    if dt_due <= as_of:
        dt_utc = dt_due.astimezone(timezone.utc)
        due_utc = dt_utc.strftime('%Y-%m-%dT%H:%M:%SZ')
        result.append((dt_due, r["id"], r["title"], due_utc))

result.sort(key=lambda x: (x[0], x[1]))

out = [
    {"id": rid, "title": title, "due_utc": due_utc}
    for (_dt, rid, title, due_utc) in result
]
print(json.dumps(out))

